def balanced(s):
    stack = []
    in_string = False
    escaped = False

    for ch in s:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
        elif ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack:
                return False
            opening = stack.pop()
            if (opening, ch) not in (("(", ")"), ("[", "]"), ("{", "}")):
                return False

    return not in_string and not stack
